<?php
$a = 2; echo $a++, ':', ++$a, ':', $a--, ':', --$a, ':', $a, "\n";
$a = '9'; $old = $a++; echo ($old === '9') + 0, ($a === 10) + 0;
$a = '2.5'; $old = $a--; echo ($old === '2.5') + 0, ($a === 1.5) + 0;
$a = null; $old = $a++; echo ($old === null) + 0, ($a === 1) + 0;
$a = -0.0; echo (++$a === 1.0) + 0, "\n";
